mapper.select:
select
,
u.username, r.rule_name
from sch_user_rule ur
left join sys_user u on ur.user_id = u.user_id
left join sch_shift_rule r on ur.rule_id = r.rule_id


        and ur.user_id = #{criteria.userId}


        and ur.rule_id = #{criteria.ruleId}


        and ur.enabled = #{criteria.enabled}


order by ur.id
